-- treaty MU-ZA ← sars-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on, signed_on, in_force_on) values ('MU', 'ZA', 'in_force', 'Signed at Maputo on 17 May 2013, in force 28 May 2015 (SARS treaty list: GG 38862 of 17 Jun 2015); replaces the 1996 treaty. Dividends 5% (qualifying company holdings) or 10%, interest 10%, royalties 5% (synthesised text with the MLI: https://www.sars.gov.za/wp-content/uploads/Legal/Agreements/Legal-INTA-DTA-MLI-2023-14-Mauritius-SA-Synthesised-text-MLI.pdf). MLI in force 1 Feb 2020 for Mauritius and 1 Jan 2023 for South Africa.', 10, 10, 'https://www.sars.gov.za/legal-counsel/international-treaties-agreements/double-taxation-agreements-protocols/dtas-and-protocols-africa/', '2026-10-03', '2027-03-31', '2013-05-17', '2015-05-28') on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest), signed_on = coalesce(excluded.signed_on, treaty.signed_on), in_force_on = coalesce(excluded.in_force_on, treaty.in_force_on);
-- treaty SC-ZA ← sars-dta
insert into treaty (country_a, country_b, status, mli_note, wht_dividend, wht_interest, source_url, verified_on, next_check_on, signed_on, in_force_on) values ('SC', 'ZA', 'in_force', 'Signed at Cape Town on 26 Aug 1998 (treaty text: https://www.sars.gov.za/wp-content/uploads/Legal/Agreements/LAPD-IntA-DTA-2012-14-DTA-Seychelles-GG-25646.pdf), in force 29 Jul 2002 (SARS treaty list, GG 25646 of 30 Oct 2003); protocol in force 15 May 2012 (GG 35396). Treaty WHT rates not read (the text is a scan), so the WHT fields stay empty.', null, null, 'https://www.sars.gov.za/legal-counsel/international-treaties-agreements/double-taxation-agreements-protocols/dtas-and-protocols-africa/', '2026-10-03', '2027-03-31', '1998-08-26', '2002-07-29') on conflict (country_a, country_b) do update set status = excluded.status, mli_note = coalesce(excluded.mli_note, treaty.mli_note), source_url = excluded.source_url, verified_on = excluded.verified_on, next_check_on = excluded.next_check_on, wht_dividend = coalesce(excluded.wht_dividend, treaty.wht_dividend), wht_interest = coalesce(excluded.wht_interest, treaty.wht_interest), signed_on = coalesce(excluded.signed_on, treaty.signed_on), in_force_on = coalesce(excluded.in_force_on, treaty.in_force_on);
